{"path": "/tmp/sv-d7b5237c31e14a8aaeade9fc5f1c8fa3/Components/Chat/MessageBubble.razor", "file_text": "<div class="message-bubble">
    <div class="message-header">
        <span class="author">@Message.Author</span>
        <span class="timestamp" title="@Message.SentAt.ToString("f")">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions is { Count: > 0 })
    {
        <div class="reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <button class="reaction-badge" @onclick="() => OnReact.InvokeAsync(reaction.Emoji)">
                    @reaction.Emoji @reaction.Users.Count
                </button>
            }
        </div>
    }

    @if (ShowThreadActions && ThreadInfo is not null)
    {
        <button class="thread-link" @onclick="() => OnOpenThread.InvokeAsync()">
            💬 @ThreadInfo.ReplyCount @(ThreadInfo.ReplyCount == 1 ? "reply" : "replies")
        </button>
    }

    @if (ShowThreadActions)
    {
        <div class="message-actions">
            <button class="action-btn" @onclick="() => OnOpenThread.InvokeAsync()" title="Reply in thread">
                💬 Reply
            </button>
            <div class="react-action-wrapper">
                <button class="action-btn" @onclick="ToggleEmojiPicker" title="Add reaction">
                    😀 React
                </button>
                @if (showEmojiPicker)
                {
                    <EmojiPicker OnSelected="HandleEmojiSelected" />
                }
            </div>
        </div>
    }
</div>

@code {
    private bool showEmojiPicker;

    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public ThreadSummary? ThreadInfo { get; set; }
    [Parameter] public bool ShowThreadActions { get; set; } = true;
    [Parameter] public EventCallback OnOpenThread { get; set; }
    [Parameter] public EventCallback<string> OnReact { get; set; }

    private void ToggleEmojiPicker() => showEmojiPicker = !showEmojiPicker;

    private async Task HandleEmojiSelected(string emoji)
    {
        showEmojiPicker = false;
        await OnReact.InvokeAsync(emoji);
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        return diff switch
        {
            { TotalSeconds: < 60 } => "just now",
            { TotalMinutes: < 60 } => $"{(int)diff.TotalMinutes} min ago",
            { TotalHours: < 24 } => $"{(int)diff.TotalHours}h ago",
            { TotalDays: < 7 } => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d")
        };
    }
}
"}

{"path": "/tmp/sv-d7b5237c31e14a8aaeade9fc5f1c8fa3/Components/Chat/MessageBubble.razor.css", "file_text": ".message-bubble {
    position: relative;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    transition: background 0.1s;
}

.message-bubble:hover {
    background: #f8f8f8;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.125rem;
}

.author {
    font-weight: 700;
    font-size: 0.9375rem;
    color: #1d1c1d;
}

.timestamp {
    font-size: 0.75rem;
    color: #888;
}

.message-content {
    font-size: 0.9375rem;
    line-height: 1.5;
    color: #1d1c1d;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.25rem;
    margin-top: 0.375rem;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.125rem 0.5rem;
    background: #f0f4ff;
    border: 1px solid #d0d8e8;
    border-radius: 999px;
    font-size: 0.8125rem;
    cursor: pointer;
    transition: background 0.1s;
}

.reaction-badge:hover {
    background: #dde4f2;
}

.thread-link {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    margin-top: 0.375rem;
    padding: 0.125rem 0.5rem;
    background: none;
    border: none;
    color: #1264a3;
    font-size: 0.8125rem;
    font-weight: 600;
    cursor: pointer;
    border-radius: 4px;
    transition: background 0.1s;
}

.thread-link:hover {
    background: #e8f0fe;
}

/* Action buttons — visible only on hover */
.message-actions {
    display: none;
    position: absolute;
    top: -0.75rem;
    right: 0.75rem;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
    overflow: visible;
}

.message-bubble:hover .message-actions {
    display: flex;
}

.action-btn {
    background: none;
    border: none;
    padding: 0.375rem 0.625rem;
    font-size: 0.8125rem;
    color: #555;
    cursor: pointer;
    white-space: nowrap;
    transition: background 0.1s, color 0.1s;
}

.action-btn:hover {
    background: #f0f0f0;
    color: #1d1c1d;
}

.react-action-wrapper {
    position: relative;
}
"}

