.thread-panel {
    display: flex;
    flex-direction: column;
    width: 340px;
    min-width: 280px;
    border-left: 1px solid #e0e0e0;
    background: #fff;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #1d1c1d;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.125rem;
    color: #888;
    cursor: pointer;
    padding: 0.25rem 0.5rem;
    border-radius: 4px;
    transition: background 0.1s, color 0.1s;
}

.close-btn:hover {
    background: #f0f0f0;
    color: #1d1c1d;
}

.thread-root {
    padding: 0.5rem 0;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
    background: #fafbfc;
}

.thread-divider {
    display: flex;
    align-items: center;
    padding: 0.5rem 1rem;
    flex-shrink: 0;
