.thread-divider span {
    font-size: 0.75rem;
    font-weight: 600;
    color: #888;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.25rem 0;
