arguments.file_text:
@page "/chat"
@rendermode InteractiveServer
@using sv_d7b5237c31e14a8aaeade9fc5f1c8fa3.Services
@using sv_d7b5237c31e14a8aaeade9fc5f1c8fa3.Components.Chat
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannel?.Id"
                    OnChannelSelected="SelectChannel" />

    <MessageArea @ref="messageAreaRef"
                 ChannelName="@(selectedChannel?.Name ?? "")"
                 ChannelDescription="@(selectedChannel?.Description ?? "")"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoadingMore="isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage"
                 OnLoadMore="LoadMoreMessages" />

    @if (activeThread is not null)
    {
        <ThreadPanel RootMessage="activeThread.RootMessage"
                     Replies="activeThread.Replies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply"
                     OnReact="HandleReaction" />
    }
</div>

@code {
    private MessageArea? messageAreaRef;
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private bool isLoadingMore;
    private ActiveThread? activeThread;

    private const int PageSize = 50;

    private sealed record ActiveThread(Message RootMessage, List<Message> Replies);

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        activeThread = null;
        threadSummaries.Clear();
        ComputeThreadSummaries();

        await ChatService.MarkChannelReadAsync(channel.Id);

        // Clear the unread badge locally
        var idx = channels.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
        {
            channels[idx] = channel with { UnreadCount = 0 };
        }
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var message = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(message);

        if (messageAreaRef is not null)
        {
            await messageAreaRef.ScrollToBottomAsync();
        }
    }

    private async Task LoadMoreMessages()
    {
        if (selectedChannel is null || isLoadingMore) return;

        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            ComputeThreadSummaries();
        }

        isLoadingMore = false;
    }

    private async Task OpenThread(int messageId)
    {
        var rootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (rootMessage is null) return;

        var replies = await ChatService.GetThreadAsync(messageId);
        activeThread = new ActiveThread(rootMessage, replies);

        // Update the thread summary
        if (replies.Count > 0)
        {
            threadSummaries[messageId] = new ThreadSummary(
                messageId, replies.Count, replies[^1].SentAt);
        }
    }

    private void CloseThread()
    {
        activeThread = null;
    }

    private async Task SendThreadReply(string content)
    {
        if (activeThread is null || selectedChannel is null) return;

        var reply = await ChatService.SendMessageAsync(
            selectedChannel.Id, content, activeThread.RootMessage.Id);
        activeThread.Replies.Add(reply);

        // Update thread summary shown on the root message
        threadSummaries[activeThread.RootMessage.Id] = new ThreadSummary(
            activeThread.RootMessage.Id,
            activeThread.Replies.Count,
            reply.SentAt);
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        UpdateReactionLocally(messages, reaction.MessageId, reaction.Emoji);
        if (activeThread is not null)
        {
            if (activeThread.RootMessage.Id == reaction.MessageId)
            {
                activeThread = activeThread with
                {
                    RootMessage = ApplyReaction(activeThread.RootMessage, reaction.Emoji)
                };
            }
            else
            {
                UpdateReactionLocally(activeThread.Replies, reaction.MessageId, reaction.Emoji);
            }
        }
    }

    private void ComputeThreadSummaries()
    {
        // Build summaries from messages that are replies (have ReplyToId)
        var replies = messages.Where(m => m.ReplyToId is not null);
        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            threadSummaries[group.Key] = new ThreadSummary(
                group.Key, group.Count(), group.Max(m => m.SentAt));
        }
    }

    private static void UpdateReactionLocally(List<Message> messageList, int messageId, string emoji)
    {
        var idx = messageList.FindIndex(m => m.Id == messageId);
        if (idx < 0) return;
        messageList[idx] = ApplyReaction(messageList[idx], emoji);
    }

    private static Message ApplyReaction(Message msg, string emoji)
    {
        var reactions = msg.Reactions?.ToList() ?? [];
        var existingIdx = reactions.FindIndex(r => r.Emoji == emoji);
        if (existingIdx >= 0)
        {
            var r = reactions[existingIdx];
            if (!r.Users.Contains("You"))
            {
                reactions[existingIdx] = r with { Users = [.. r.Users, "You"] };
            }
        }
        else
        {
            reactions.Add(new Reaction(emoji, ["You"]));
        }
        return msg with { Reactions = reactions };
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

